local CommonRankMyCell = Class('CommonRankMyCell')

--region lifecycle

function CommonRankMyCell:__init()
	self.bossType = BossRankType.CakeShopBoss
end

function CommonRankMyCell:__delete()
	self.bossType = nil
	self.rankData = nil
	self._rankInfo = nil
	self._myRankInfo = nil
	self._playerDojo = nil
	self._rankListVo = nil
	self._rankText = nil
	self._playerComp = nil
	self._headScr = nil
	self._rewardsScr = nil
end

function CommonRankMyCell:Awake()
	---@type PlayerComponent
	self._playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
	---@type CommonPlayerHeadNode
	self._headScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
	---@type CommonGoodsList
	self._rewardsScr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
	SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnDetailHandler))
end

function CommonRankMyCell:SetIgnoreClick(ignore)
	self.isIgnore = ignore
end

function CommonRankMyCell:OnDestroy()
	self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
--endregion init

--region handler
function CommonRankMyCell:OnBtnDetailHandler()
	if isNull(self._rankInfo) and self.isIgnore then
		return
	end
	local isInList = false
	for _, rank in ipairs(self._rankInfo) do
		if checkString(rank.playerId) == self._playerDojo.playerId then
			isInList = true
			GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, rank.team, nil, nil, self._playerDojo.playerName)
		end
	end
	if not isInList then
		GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, self._myRankInfo.team, '', nil, self._playerDojo.playerName)
	end
end
--endregion handler

--region public
function CommonRankMyCell:Refresh(data, entryCtr, rankType)
	self.entryCtr = entryCtr
	self.rankData = data
	self.rankType = rankType
	self._rankInfo = self.rankData.rank or self.rankData.rankInfo
	self._myRankInfo = self.rankData.playerRank
	self._playerDojo = self._playerComp:GetPlayerDojo()
	self._rankListVo = self:GetRankRewardByType()
	self._rankText = checkString(self._myRankInfo.ranking)

	local myRankNum = checkNumber(self._myRankInfo.ranking)
	local type = checkNumber(self._myRankInfo.type)
	---有伤害说明有排名 只有百分比才要取名字
	if type > 0 and type == RankType.Percentage then
		for _, vo in ipairs(self._rankListVo) do
			---@type MidFestivalBossRankRewardVo
			if checkNumber(vo.type) == type then
				if myRankNum >= checkNumber(vo.upperLimit) and myRankNum <= checkNumber(vo.lowerLimit) then
					self._rankText = vo.name
				end
			end
		end
	end
	
	self:RefreshUI()
end

function CommonRankMyCell:GetRankRewardByType()
	if self.rankType == 1 then
		return self.entryCtr:GetBossRankRewardVos()
	else
		return self.entryCtr:GetSplitRankRewardsVos()
	end
	return {}
end
--endregion public

function CommonRankMyCell:RefreshBeginnerBossMyCell(data, entryCtr)
	self.entryCtr = entryCtr
	self.rankData = data
	self._rankInfo = self.rankData.rank or self.rankData.rankInfo
	self._myRankInfo = self.rankData.playerRank
	self._playerDojo = self._playerComp:GetPlayerDojo()
	self._rankListVo = self.entryCtr:GetBossRankRewardVos()
	self._rankText = checkString(self._myRankInfo.ranking)
	
	local myRankNum = checkNumber(self._myRankInfo.ranking)
	local type = checkNumber(self._myRankInfo.type)
	---有伤害说明有排名 只有百分比才要取名字
	if type > 0 and myRankNum > 200 then
		for _, vo in ipairs(self._rankListVo) do
			---@type MidFestivalBossRankRewardVo
			if checkNumber(vo.type) == type then
				if myRankNum >= checkNumber(vo.upperLimit) and myRankNum <= checkNumber(vo.lowerLimit) then
					self._rankText = vo.name
				end
			end
		end
	end
	self:RefreshUI()
end

--region private
function CommonRankMyCell:RefreshUI()
	-- 基本信息
	CfUtils.FillText(self.TxtName, self._playerDojo.playerName)
	CfUtils.FillText(self.TextLevel, "Lv." .. self._playerDojo.level)
	self._headScr:FreshAvatarFrame(self._playerDojo.playerAvatar, self._playerDojo.playerAvatarFrame)
	
	-- 排行信息
	if checkNumber(self._myRankInfo.hurt) > 0 then
		CfUtils.SetUISwitchImage(self.ImgRank, checkNumber(self._myRankInfo.ranking))
		CfUtils.FillText(self.Txtranking, self._rankText)
		CfUtils.SetActive(self.TxtNo, false)
		CfUtils.SetActive(self.RankNode, true)
	else
		-- 未造成伤害
		CfUtils.SetActive(self.TxtNo, true)
		CfUtils.SetActive(self.RankNode, false)
	end
	
	CfUtils.SetActive(self.ImgRank, checkNumber(self._myRankInfo.hurt) > 0)
	-- 伤害和奖励
	CfUtils.FillText(self.TxtDamage, checkString(self._myRankInfo.hurt))
	
	local rewards = {}
	local type = checkNumber(self._myRankInfo.type)
	local myRank = checkNumber(self._myRankInfo.ranking)
	for _, rank in ipairs(self._rankListVo)  do
		---@type ActivityCakeBossRankVo
		local rankVo = rank
		if checkNumber(myRank) >= rankVo.upperLimit and checkNumber(myRank) <= rankVo.lowerLimit and rankVo.type == type then
			local rewardCount = table.count(rankVo.reward)
			for i = 1, rewardCount do
				local reward = {
					goodsId = rankVo.reward[i],
					num = rankVo.rewardNum[i],
				}
				table.insert(rewards, reward)
			end
		end
	end
	CfUtils.SetActive(self.TextNoReward, table.count(rewards) == 0)
	self._rewardsScr:FreshBaseUI(rewards)
	
	if not self.isIgnore then
		CfUtils.SetActive(self.BtnDetails, checkNumber(self._myRankInfo.hurt) > 0)
	else
		CfUtils.SetActive(self.BtnDetails,false)
	end
	
	
	CfUtils.SetActive(self.controller.gameObject, true)
end
--endregion private

--region get / set
--endregion get / set

return CommonRankMyCell